param(
    [Parameter(Mandatory=$true)][string]$Url,
    [Parameter(Mandatory=$true)][string]$Out,
    [int]$Parts = 8
)
$ErrorActionPreference = 'Stop'
$log = "$Out.log"
function Log($m){ Add-Content -Path $log -Value "$(Get-Date -Format HH:mm:ss) $m" }

try {
    # Get total size via HEAD (follow redirects, take last content-length)
    $headers = & curl.exe -sIL $Url
    $size = 0
    foreach ($h in $headers) { if ($h -match '^content-length:\s*(\d+)') { $size = [long]$Matches[1] } }
    if ($size -le 0) { throw "Could not determine file size" }
    Log "Total size: $([math]::Round($size/1MB,1)) MB in $Parts parts"

    $chunk = [math]::Ceiling($size / $Parts)
    $procs = @()
    for ($i = 0; $i -lt $Parts; $i++) {
        $start = $i * $chunk
        $end = [math]::Min($start + $chunk - 1, $size - 1)
        if ($start -gt $end) { break }
        $partFile = "$Out.part$i"
        $expected = $end - $start + 1
        # Skip if part already complete (resume support)
        if ((Test-Path $partFile) -and (Get-Item $partFile).Length -eq $expected) { continue }
        Remove-Item $partFile -Force -ErrorAction SilentlyContinue
        $p = Start-Process -FilePath "curl.exe" -ArgumentList '-sS','--retry','10','--retry-delay','3','--retry-all-errors','-r',"$start-$end",'-o',$partFile,$Url -WindowStyle Hidden -PassThru
        $procs += $p
        Start-Sleep -Milliseconds 200
    }
    Log "Launched $($procs.Count) chunk downloads"

    # Poll until all parts complete
    $nParts = $i
    while ($true) {
        Start-Sleep -Seconds 5
        $done = 0; $totalBytes = 0
        for ($j = 0; $j -lt $nParts; $j++) {
            $pf = "$Out.part$j"
            $s = ($j * $chunk)
            $e = [math]::Min($s + $chunk - 1, $size - 1)
            $exp = $e - $s + 1
            if ((Test-Path $pf) -and (Get-Item $pf).Length -eq $exp) { $done++ ; $totalBytes += $exp }
            elseif (Test-Path $pf) { $totalBytes += (Get-Item $pf).Length }
        }
        Log ("Progress: {0:P1} ({1:N0}/{2:N0} MB)" -f ($totalBytes/$size), ($totalBytes/1MB), ($size/1MB))
        if ($done -eq $nParts) { break }
    }

    # Assemble
    $partList = @()
    for ($j = 0; $j -lt $nParts; $j++) { $partList += "$Out.part$j" }
    $cmdArgs = "/c copy /b " + ($partList -join '+') + ' "' + $Out + '" /y'
    & cmd.exe $cmdArgs.Split(' ') | Out-Null
    if (-not (Test-Path $Out)) { throw "Assembly failed" }
    $finalSize = (Get-Item $Out).Length
    if ($finalSize -ne $size) { throw "Final size mismatch: $finalSize vs $size" }
    Remove-Item ($partList) -Force
    Log "DONE: $Out ($([math]::Round($finalSize/1MB,1)) MB)"
}
catch {
    Log "ERROR: $_"
    exit 1
}

extends Node3D

const GRAV := 9.81
const DEADZONE := 0.06

@export var max_tilt_deg: float = 11.0
@export var smoothing: float = 6.0

var input_enabled := true
var _target := Vector2.ZERO
var _current := Vector2.ZERO

func _physics_process(delta: float) -> void:
	if input_enabled:
		_target = _read_tilt()
	else:
		_target = Vector2.ZERO
	_current = _current.lerp(_target, clampf(smoothing * delta, 0.0, 1.0))
	var rad := deg_to_rad(max_tilt_deg)
	rotation.z = lerpf(rotation.z, -_current.x * rad, clampf(smoothing * delta, 0.0, 1.0))
	rotation.x = lerpf(rotation.x, -_current.y * rad, clampf(smoothing * delta, 0.0, 1.0))

func _read_tilt() -> Vector2:
	var g := Input.get_gravity()
	if g.length() < 1.0:
		g = Input.get_accelerometer()
	var t := Vector2.ZERO
	if g.length() >= 1.0:
		t = Vector2(g.x / GRAV, g.y / GRAV)
	var kb := Input.get_vector("tilt_left", "tilt_right", "tilt_down", "tilt_up")
	t += kb
	t = t.clamp(Vector2.ONE * -1.0, Vector2.ONE)
	if t.length() < DEADZONE:
		return Vector2.ZERO
	return t

class_name Ghost
extends CharacterBody3D

const SPEEDS := [2.4, 2.25, 2.55, 2.1]
const CHASE_SECS := 7.0
const SCATTER_SECS := 4.0
const ARRIVE_DIST := 0.18

var ghost_index := 0
var speed := 2.3
var player: PacBall

var _color: Color
var _scatter_corner := Vector2i.ZERO
var _next_cell := Vector2i(-99, -99)
var _prev_cell := Vector2i(-99, -99)
var _timer := 0.0
var _chasing := true
var _eyes: Node3D
var _frozen := false

func setup(index: int, spawn_cell: Vector2i) -> void:
	ghost_index = index
	_color = MazeData.GHOST_COLORS[index % MazeData.GHOST_COLORS.size()]
	_scatter_corner = MazeData.SCATTER_CORNERS[index % MazeData.SCATTER_CORNERS.size()]
	speed = SPEEDS[index % SPEEDS.size()]
	_timer = float(index) * 2.5
	position = MazeData.cell_to_world(spawn_cell)
	_next_cell = spawn_cell

func _ready() -> void:
	collision_layer = 4
	collision_mask = 1 | 2 | 4
	var col := CollisionShape3D.new()
	var cap := CapsuleShape3D.new()
	cap.radius = 0.42
	cap.height = 1.15
	col.shape = cap
	col.position.y = 0.58
	add_child(col)

	var body_mat := StandardMaterial3D.new()
	body_mat.albedo_color = _color
	body_mat.emission_enabled = true
	body_mat.emission = _color
	body_mat.emission_energy_multiplier = 0.45
	body_mat.roughness = 0.5
	var body := MeshInstance3D.new()
	var bmesh := CapsuleMesh.new()
	bmesh.radius = 0.42
	bmesh.height = 1.15
	body.mesh = bmesh
	body.material_override = body_mat
	add_child(body)

	var skirt := MeshInstance3D.new()
	var smesh := CylinderMesh.new()
	smesh.top_radius = 0.42
	smesh.bottom_radius = 0.30
	smesh.height = 0.25
	skirt.mesh = smesh
	skirt.material_override = body_mat
	skirt.position.y = -0.48
	add_child(skirt)

	_eyes = Node3D.new()
	add_child(_eyes)
	for side in [-1.0, 1.0]:
		var eye := MeshInstance3D.new()
		var em := SphereMesh.new()
		em.radius = 0.11
		em.height = 0.22
		eye.mesh = em
		var white := StandardMaterial3D.new()
		white.albedo_color = Color.WHITE
		eye.material_override = white
		eye.position = Vector3(0.17 * side, 0.72, 0.30)
		_eyes.add_child(eye)
		var pupil := MeshInstance3D.new()
		var pu := SphereMesh.new()
		pu.radius = 0.05
		pu.height = 0.1
		pupil.mesh = pu
		var blue := StandardMaterial3D.new()
		blue.albedo_color = Color(0.1, 0.15, 0.6)
		pupil.material_override = blue
		pupil.position = Vector3(0.17 * side, 0.72, 0.39)
		_eyes.add_child(pupil)

	var catch_area := Area3D.new()
	catch_area.collision_layer = 0
	catch_area.collision_mask = 2
	var ccol := CollisionShape3D.new()
	var cshape := SphereShape3D.new()
	cshape.radius = 0.62
	ccol.shape = cshape
	ccol.position.y = 0.58
	catch_area.add_child(ccol)
	add_child(catch_area)
	catch_area.body_entered.connect(_on_body_entered)

func freeze() -> void:
	_frozen = true

func unfreeze() -> void:
	_frozen = false

func _physics_process(delta: float) -> void:
	if _frozen or player == null or not is_instance_valid(player):
		return
	_timer += delta
	var cycle := fmod(_timer, CHASE_SECS + SCATTER_SECS)
	_chasing = cycle < CHASE_SECS

	if not is_on_floor():
		var down := -global_transform.basis.y.normalized()
		velocity += down * 9.8 * delta
	else:
		var down := -global_transform.basis.y.normalized()
		velocity += down * 9.8 * delta

	var my_cell := MazeData.world_to_cell(global_position)
	var cell_center := MazeData.cell_to_world(my_cell)
	var flat_pos := Vector3(global_position.x, cell_center.y, global_position.z)
	if flat_pos.distance_to(cell_center) < ARRIVE_DIST or _next_cell == Vector2i(-99, -99):
		_decide_next(my_cell)

	var target_world := MazeData.cell_to_world(_next_cell)
	var to_target := target_world - global_position
	to_target.y = 0.0
	if to_target.length() > 0.05:
		var desired := to_target.normalized() * speed
		desired.y = velocity.y
		velocity.x = lerpf(velocity.x, desired.x, clampf(8.0 * delta, 0.0, 1.0))
		velocity.z = lerpf(velocity.z, desired.z, clampf(8.0 * delta, 0.0, 1.0))

	up_direction = global_transform.basis.y.normalized()
	move_and_slide()

	var hv := Vector3(velocity.x, 0, velocity.z)
	if hv.length() > 0.2:
		var yaw := atan2(-hv.x, -hv.z) + PI
		_eyes.rotation.y = lerp_angle(_eyes.rotation.y, yaw, clampf(8.0 * delta, 0.0, 1.0))
	_eyes.position.y = 0.02 * sin(Time.get_ticks_msec() / 180.0 + ghost_index)

func _decide_next(my_cell: Vector2i) -> void:
	if my_cell == _next_cell:
		_prev_cell = my_cell
	var target := _scatter_corner
	if _chasing and player != null:
		target = MazeData.world_to_cell(player.global_position)
	var step := MazeData.bfs_next_step(my_cell, target)
	if step == my_cell:
		step = _pick_fallback(my_cell, target)
	if step == _prev_cell and my_cell != _prev_cell:
		var alt := _pick_alternative(my_cell, target)
		if alt != my_cell:
			step = alt
	_next_cell = step

func _pick_fallback(my_cell: Vector2i, target: Vector2i) -> Vector2i:
	var best := my_cell
	var best_d := 999999
	for n in MazeData.neighbors(my_cell):
		var d := absi(n.x - target.x) + absi(n.y - target.y)
		if d < best_d:
			best_d = d
			best = n
	return best

func _pick_alternative(my_cell: Vector2i, target: Vector2i) -> Vector2i:
	var best := my_cell
	var best_d := 999999
	for n in MazeData.neighbors(my_cell):
		if n == _prev_cell:
			continue
		var d := absi(n.x - target.x) + absi(n.y - target.y)
		if d < best_d:
			best_d = d
			best = n
	return best

func _on_body_entered(body: Node3D) -> void:
	if body is PacBall:
		Game.player_caught()

