func _on_star_collected() -> void:
	var id := Game.random_core_power()
	Game.start_power(id)
	var p: Dictionary = Game.POWERS.get(id, {})
	hud.flash_message("★ STAR POWER: %s" % str(p.get("name", id)), 2.5)
